/// <reference types="vite/client" />
import { convexTest } from "convex-test";
import type { SchemaDefinition, GenericSchema } from "convex/server";
import appSchema from "../example/convex/schema";
import componentSchema from "../src/component/schema";
import {
  registerMockSteelClient,
  resetMockSteelClient,
  type MockSteelClientOptions,
  componentModules,
} from "../src/test";

const appModules = import.meta.glob("../example/convex/**/*.ts");

const ACTION_PATHS = new Set([
  "sessions:refresh", "sessions:refreshMany", "sessions:release",
  "sessions:releaseAll", "sessions:create", "sessions:computer",
  "sessions:context", "sessions:events", "sessions:liveDetails",
  "sessionFiles:list", "sessionFiles:upload", "sessionFiles:delete", "sessionFiles:deleteAll",
  "captchas:status", "captchas:solve", "captchas:solveImage",
  "profiles:list", "profiles:get", "profiles:create", "profiles:update",
  "credentials:list", "credentials:create", "credentials:update", "credentials:delete",
  "extensions:list", "extensions:upload", "extensions:update", "extensions:delete",
  "extensions:deleteAll", "extensions:download",
  "files:list", "files:upload", "files:delete", "files:download",
  "topLevel:screenshot", "topLevel:scrape", "topLevel:pdf",
]);

const MUTATION_PATHS = new Set([
  "sessions:upsert",
]);

export type FunctionPath = {
  componentPath: string;
  udfPath: string;
  type: "action" | "query" | "mutation";
};

export const createSteelTestHarness = () => {
  const t = convexTest(
    appSchema as SchemaDefinition<GenericSchema, boolean>,
    appModules,
  );
  t.registerComponent(
    "steel",
    componentSchema as SchemaDefinition<GenericSchema, boolean>,
    componentModules as unknown as Record<string, () => Promise<any>>,
  );

  const makeFunctionRef = (componentPath: string, udfPath: string) => {
    const ref = {} as any;
    const [module, fn] = udfPath.split(":");
    ref[Symbol.for("toReferencePath")] = `_reference/app/${componentPath}/${module}/${fn}`;
    return ref;
  };

  const fun = async (fn: FunctionPath, args: Record<string, unknown>) => {
    const ref = makeFunctionRef(fn.componentPath, fn.udfPath);
    if (fn.type === "action") return t.action(ref, args);
    if (fn.type === "mutation") return t.mutation(ref, args);
    return t.query(ref, args);
  };

  return { ...t, fun };
};

export const steelFunction = (udfPath: string): FunctionPath => ({
  componentPath: "steel",
  udfPath,
  type: ACTION_PATHS.has(udfPath) ? "action" : MUTATION_PATHS.has(udfPath) ? "mutation" : "query",
});

export const resetSteelClientMock = (): void => resetMockSteelClient();

export const createMockSteelClient = (options: MockSteelClientOptions = { sessions: [] }) => {
  resetMockSteelClient();
  return registerMockSteelClient(options);
};

import { beforeEach, describe, expect, test } from "vitest";

import {
  createMockSteelClient,
  createSteelTestHarness,
  resetSteelClientMock,
  steelFunction,
} from "./sessionTestUtils";

const liveApiKey = typeof process !== "undefined" ? process.env.STEEL_API_KEY : undefined;
const hasLiveMode =
  typeof liveApiKey === "string" &&
  liveApiKey.trim().length > 0 &&
  process.env.STEEL_LIVE_TEST === "1";

describe("steel sessions integration smoke tests", () => {
  beforeEach(() => {
    createMockSteelClient();
  });

  test("runs create, refresh, and release flow for a single tenant", async () => {
    const t = createSteelTestHarness();
    const ownerId = "tenant-integration-primary";

    const created = await t.fun(steelFunction("sessions:create"), {
      ownerId,
      apiKey: "[REDACTED]",
      includeRaw: true,
      sessionArgs: {
        image: "chrome",
        timeout: 240,
      },
    });
    expect(created.ownerId).toBe(ownerId);

    const refreshed = await t.fun(steelFunction("sessions:refresh"), {
      externalId: created.externalId,
      ownerId,
      apiKey: "[REDACTED]",
    });
    expect(refreshed.externalId).toBe(created.externalId);

    const released = await t.fun(steelFunction("sessions:release"), {
      externalId: created.externalId,
      ownerId,
      apiKey: "[REDACTED]",
    });
    expect(released.status).toBe("released");

    const listAfterRelease = await t.fun(steelFunction("sessions:list"), {
      ownerId,
      status: "released",
    });
    expect(listAfterRelease.items).toEqual(
      expect.arrayContaining([
        expect.objectContaining({
          externalId: created.externalId,
          status: "released",
          ownerId,
        }),
      ]),
    );
  });

  test("keeps tenant-specific visibility separate", async () => {
    const t = createSteelTestHarness();
    const ownerOne = "tenant-integration-one";
    const ownerTwo = "tenant-integration-two";

    const tenantOneSession = await t.fun(steelFunction("sessions:create"), {
      ownerId: ownerOne,
      apiKey: "[REDACTED]",
      sessionArgs: { image: "chrome", timeout: 120 },
    });

    const tenantTwoSession = await t.fun(steelFunction("sessions:create"), {
      ownerId: ownerTwo,
      apiKey: "[REDACTED]",
      sessionArgs: { image: "firefox", timeout: 120 },
    });

    const ownerOneList = await t.fun(steelFunction("sessions:list"), { ownerId: ownerOne });
    expect(ownerOneList.items).toHaveLength(1);
    expect(ownerOneList.items[0].ownerId).toBe(ownerOne);
    expect(ownerOneList.items[0].externalId).toBe(tenantOneSession.externalId);

    const ownerTwoList = await t.fun(steelFunction("sessions:list"), { ownerId: ownerTwo });
    expect(ownerTwoList.items).toHaveLength(1);
    expect(ownerTwoList.items[0].ownerId).toBe(ownerTwo);
    expect(ownerTwoList.items[0].externalId).toBe(tenantTwoSession.externalId);

    const crossTenantRead = t.fun(steelFunction("sessions:getByExternalId"), {
      externalId: tenantOneSession.externalId,
      ownerId: ownerTwo,
    });
    await expect(crossTenantRead).rejects.toThrow(
      /ownerId mismatch for session query|Missing ownerId/i,
    );
  });
});

describe.runIf(hasLiveMode)("steel sessions live smoke tests", () => {
  beforeEach(() => {
    resetSteelClientMock();
  });

  test("performs live smoke check when STEEL_API_KEY is provided", async () => {
    const t = createSteelTestHarness();
    const ownerId = `tenant-live-${Math.random().toString(36).slice(2, 10)}`;
    const apiKey = [REDACTED];

    const created = await t.fun(steelFunction("sessions:create"), {
      ownerId,
      apiKey,
      sessionArgs: { image: "chrome", timeout: 120 },
    });
    expect(created.externalId).toEqual(expect.any(String));

    const refreshed = await t.fun(steelFunction("sessions:refresh"), {
      externalId: created.externalId,
      ownerId,
      apiKey,
    });
    expect(refreshed.externalId).toBe(created.externalId);

    const released = await t.fun(steelFunction("sessions:release"), {
      externalId: created.externalId,
      ownerId,
      apiKey,
    });
    expect(released.status).toBe("released");
  });
});

import { beforeEach, describe, expect, test } from "vitest";

import { createMockSteelClient, createSteelTestHarness, steelFunction } from "./sessionTestUtils";

describe("steel sessions unit tests", () => {
  beforeEach(() => {
    createMockSteelClient();
  });

  test("syncs remote session refresh into local cache", async () => {
    const t = createSteelTestHarness();
    createMockSteelClient({
      sessions: [
        {
          externalId: "sync-live-001",
          status: "failed",
          createdAt: 1_700_000_000_020,
          updatedAt: 1_700_000_000_020,
          lastSyncedAt: 1_700_000_000_020,
          debugUrl: "https://remote.example.com/sync-live-001",
          sessionViewerUrl: "https://viewer.example.com/sync-live-001",
          websocketUrl: "wss://ws.example.com/sync-live-001",
          timeout: 600,
          duration: 1_000,
          creditsUsed: 12,
          eventCount: 4,
          proxyBytesUsed: 800,
          profileId: "profile-sync",
          region: "us-east-1",
          headless: true,
          isSelenium: false,
          userAgent: "test-agent/0.2",
        },
      ],
    });
    const ownerId = "tenant-sync-unit";

    await t.fun(steelFunction("sessions:upsert"), {
      externalId: "sync-live-001",
      status: "released",
      createdAt: 1_700_000_000_000,
      updatedAt: 1_700_000_000_000,
      lastSyncedAt: 1_700_000_000_000,
      ownerId,
    });

    const refreshed = await t.fun(steelFunction("sessions:refresh"), {
      externalId: "sync-live-001",
      ownerId,
      apiKey: "[REDACTED]",
      includeRaw: true,
    });

    expect(refreshed.status).toBe("failed");

    const cached = await t.fun(steelFunction("sessions:getByExternalId"), {
      externalId: "sync-live-001",
      ownerId,
    });
    expect(cached).not.toBeNull();
    expect(cached?.status).toBe("failed");
  });

  test("upsert updates existing session rows", async () => {
    const t = createSteelTestHarness();
    const ownerId = "tenant-upsert-unit";

    await t.fun(steelFunction("sessions:upsert"), {
      externalId: "upsert-001",
      status: "live",
      createdAt: 1_700_000_010_000,
      updatedAt: 1_700_000_010_000,
      lastSyncedAt: 1_700_000_010_000,
      ownerId,
      timeout: 600,
      duration: 10,
      userAgent: "before-update",
    });

    await t.fun(steelFunction("sessions:upsert"), {
      externalId: "upsert-001",
      status: "released",
      createdAt: 1_700_000_010_000,
      updatedAt: 1_700_000_020_000,
      lastSyncedAt: 1_700_000_020_000,
      ownerId,
      timeout: 600,
      duration: 20,
      userAgent: "after-update",
    });

    const updated = await t.fun(steelFunction("sessions:getByExternalId"), {
      externalId: "upsert-001",
      ownerId,
    });

    expect(updated).not.toBeNull();
    expect(updated?.status).toBe("released");
    expect(updated?.duration).toBe(20);
    expect(updated?.updatedAt).toBe(1_700_000_020_000);
  });

  test("lists tenant-scoped sessions", async () => {
    const t = createSteelTestHarness();
    const ownerA = "tenant-list-a";
    const ownerB = "tenant-list-b";

    await t.fun(steelFunction("sessions:upsert"), {
      externalId: "list-a-live",
      status: "live",
      createdAt: 1_700_000_030_000,
      updatedAt: 1_700_000_030_100,
      lastSyncedAt: 1_700_000_030_100,
      ownerId: ownerA,
    });
    await t.fun(steelFunction("sessions:upsert"), {
      externalId: "list-a-released",
      status: "released",
      createdAt: 1_700_000_031_000,
      updatedAt: 1_700_000_031_100,
      lastSyncedAt: 1_700_000_031_100,
      ownerId: ownerA,
    });
    await t.fun(steelFunction("sessions:upsert"), {
      externalId: "list-b-live",
      status: "live",
      createdAt: 1_700_000_032_000,
      updatedAt: 1_700_000_032_100,
      lastSyncedAt: 1_700_000_032_100,
      ownerId: ownerB,
    });

    const ownerAList = await t.fun(steelFunction("sessions:list"), { ownerId: ownerA });
    expect(ownerAList.items).toHaveLength(2);
    expect(ownerAList.items.every((item: { ownerId: string }) => item.ownerId === ownerA)).toBe(
      true,
    );

    const ownerBList = await t.fun(steelFunction("sessions:list"), { ownerId: ownerB });
    expect(ownerBList.items).toHaveLength(1);
    expect(ownerBList.items[0].ownerId).toBe(ownerB);
    expect(ownerBList.items[0].externalId).toBe("list-b-live");

    const ownerALive = await t.fun(steelFunction("sessions:list"), {
      ownerId: ownerA,
      status: "live",
    });
    expect(ownerALive.items).toHaveLength(1);
    expect(ownerALive.items[0].status).toBe("live");
  });

  test("release is idempotent for already released sessions", async () => {
    const t = createSteelTestHarness();
    const ownerId = "tenant-release-unit";
    const mockClient = createMockSteelClient();

    await t.fun(steelFunction("sessions:upsert"), {
      externalId: "released-idempotent-001",
      status: "released",
      createdAt: 1_700_000_040_000,
      updatedAt: 1_700_000_040_000,
      lastSyncedAt: 1_700_000_040_000,
      ownerId,
    });

    const first = await t.fun(steelFunction("sessions:release"), {
      externalId: "released-idempotent-001",
      ownerId,
      apiKey: "[REDACTED]",
    });
    const second = await t.fun(steelFunction("sessions:release"), {
      externalId: "released-idempotent-001",
      ownerId,
      apiKey: "[REDACTED]",
    });

    expect(first.status).toBe("released");
    expect(second.status).toBe("released");
    expect(
      mockClient.__calls.sessions.some((item: { method: string }) => item.method === "release"),
    ).toBe(false);
  });
});

import { beforeEach, describe, expect, test } from "vitest";

import { createMockSteelClient, createSteelTestHarness, steelFunction } from "./sessionTestUtils";

describe("steel full surface unit tests", () => {
  beforeEach(() => {
    createMockSteelClient();
  });

  test("runs sessions utility actions", async () => {
    const t = createSteelTestHarness();
    const ownerId = "tenant-full-sessions";

    const created = await t.fun(steelFunction("sessions:create"), {
      ownerId,
      apiKey: "[REDACTED]",
      sessionArgs: { image: "chrome", timeout: 120 },
    });

    const computer = await t.fun(steelFunction("sessions:computer"), {
      ownerId,
      apiKey: "[REDACTED]",
      externalId: created.externalId,
      commandArgs: { action: "wait", duration: 1 },
    });
    expect(computer).toMatchObject({ action: "computer", sessionId: created.externalId });

    const context = await t.fun(steelFunction("sessions:context"), {
      ownerId,
      apiKey: "[REDACTED]",
      externalId: created.externalId,
    });
    expect(context).toMatchObject({ action: "context", sessionId: created.externalId });

    const events = await t.fun(steelFunction("sessions:events"), {
      ownerId,
      apiKey: "[REDACTED]",
      externalId: created.externalId,
    });
    expect(events).toEqual(expect.arrayContaining([expect.objectContaining({ type: "event" })]));

    const liveDetails = await t.fun(steelFunction("sessions:liveDetails"), {
      ownerId,
      apiKey: "[REDACTED]",
      externalId: created.externalId,
    });
    expect(liveDetails).toMatchObject({ sessionId: created.externalId });
  });

  test("runs session files and captchas actions", async () => {
    const t = createSteelTestHarness();
    const ownerId = "tenant-full-session-assets";
    const sessionExternalId = "session-live-001";

    const uploadedFile = await t.fun(steelFunction("sessionFiles:upload"), {
      ownerId,
      apiKey: "[REDACTED]",
      sessionExternalId,
      url: "https://example.com/file.txt",
      path: "file.txt",
    });
    expect(uploadedFile).toMatchObject({ sessionExternalId, path: "file.txt" });

    const listedFiles = await t.fun(steelFunction("sessionFiles:list"), {
      ownerId,
      apiKey: "[REDACTED]",
      sessionExternalId,
    });
    expect(Array.isArray(listedFiles.items)).toBe(true);

    const deleteResult = await t.fun(steelFunction("sessionFiles:delete"), {
      ownerId,
      apiKey: "[REDACTED]",
      sessionExternalId,
      path: "file.txt",
    });
    expect(deleteResult).toMatchObject({ ok: true });

    const deleteAllResult = await t.fun(steelFunction("sessionFiles:deleteAll"), {
      ownerId,
      apiKey: "[REDACTED]",
      sessionExternalId,
    });
    expect(deleteAllResult).toMatchObject({ ok: true });

    const captchaStatus = await t.fun(steelFunction("captchas:status"), {
      ownerId,
      apiKey: "[REDACTED]",
      sessionExternalId,
      pageId: "page-1",
      persistSnapshot: true,
    });
    expect(captchaStatus).toMatchObject({ pageId: "page-1" });

    const solveResult = await t.fun(steelFunction("captchas:solve"), {
      ownerId,
      apiKey: "[REDACTED]",
      sessionExternalId,
      pageId: "page-1",
    });
    expect(solveResult).toMatchObject({ solved: true });

    const solveImageResult = await t.fun(steelFunction("captchas:solveImage"), {
      ownerId,
      apiKey: "[REDACTED]",
      sessionExternalId,
      imageXPath: "//img[@id='captcha']",
      inputXPath: "//input[@id='captcha']",
    });
    expect(solveImageResult).toMatchObject({ solved: true });
  });

  test("runs profiles credentials extensions and global files actions", async () => {
    const t = createSteelTestHarness();
    const ownerId = "tenant-full-metadata";

    const createdProfile = await t.fun(steelFunction("profiles:create"), {
      ownerId,
      apiKey: "[REDACTED]",
      profileArgs: { name: "Test profile" },
    });
    expect(createdProfile.externalId).toBe("profile-new");

    const updatedProfile = await t.fun(steelFunction("profiles:update"), {
      ownerId,
